function buildFilters(filters) {
  const clauses = [];
  const params = [];
  if (filters.category) {
    params.push(filters.category);
    clauses.push('category = $' + params.length);
  }
  if (filters.inStock) {
    clauses.push('stock > 0');
  }
  return { where: clauses.length ? 'WHERE ' + clauses.join(' AND ') : '', params };
}

module.exports = { buildFilters };
